<?php
if (!defined('ABSPATH')) exit;

if (!function_exists('get_field')) return;

$theme_uri = get_template_directory_uri();
$placeholder_img = $theme_uri . '/images/content/categories/furniture.webp';
$placeholder_bg  = $theme_uri . '/images/content/categories/grid-blue.svg';

function strike_img_url_from_acf($field) {
    if (empty($field)) return '';
    if (is_array($field) && !empty($field['url'])) return $field['url'];
    if (is_numeric($field)) return wp_get_attachment_image_url((int)$field, 'full') ?: '';
    if (is_string($field)) return $field;
    return '';
}

function strike_popular_flags($term_id) {
    $flags = get_field('populyarnaya_kategoriya_na_glavnoj_v', 'product_cat_' . $term_id);
    if (!$flags) return [];
    if (is_string($flags)) return [$flags];
    if (is_array($flags)) return array_values(array_filter($flags));
    return [];
}

function strike_cat_media($term_id) {
    $g = get_field('kartiki_otobrazheniya', 'product_cat_' . $term_id);
    $img = $g['kartinka'] ?? '';
    $bg  = $g['fon'] ?? '';
    return [
        'img' => strike_img_url_from_acf($img),
        'bg'  => strike_img_url_from_acf($bg),
    ];
}

function strike_render_cat_card($term, $img_url, $bg_url, $placeholder_img, $placeholder_bg) {
    $link = get_term_link($term);
    $title = $term->name;
    $img_url = $img_url ?: $placeholder_img;
    $bg_url  = $bg_url ?: $placeholder_bg;
    ?>
    <a href="<?= esc_url($link); ?>" class="popular-categories-item relative flex flex-col justify-between bg-white rounded-xl overflow-hidden">
        <div class="relative z-10 p-3">
            <p class="popular-categories-item__title font-medium text-lg/[110%] text-center"><?= esc_html($title); ?></p>
        </div>
        <img class="popular-categories-item__img relative z-10 object-contain h-40 mx-auto"
             src="<?= esc_url($img_url); ?>" alt="<?= esc_attr($title); ?>" />
        <img class="popular-categories-item__bg absolute z-0 bottom-0 left-0 object-contain w-full h-40"
             style="object-fit: cover" src="<?= esc_url($bg_url); ?>" alt="Icon" />
    </a>
    <?php
}

function strike_render_cats_grid($terms, $placeholder_img, $placeholder_bg) {
    if (empty($terms)) return;
    $patterns = [
        'grid grid-cols-[180px_180px_250px_180px_180px_250px] gap-3 mb-3',
        'grid grid-cols-[180px_180px_250px_250px_180px_180px] gap-3',
    ];
    $chunks = array_chunk($terms, 6);
    foreach ($chunks as $i => $chunk) {
        $class = $patterns[$i % 2];
        echo '<div class="popular-categories__items ' . esc_attr($class) . '">';
        foreach ($chunk as $term) {
            $m = strike_cat_media($term->term_id);
            strike_render_cat_card($term, $m['img'], $m['bg'], $placeholder_img, $placeholder_bg);
        }
        echo '</div>';
    }
}

$all_terms = get_terms([
    'taxonomy'   => 'product_cat',
    'hide_empty' => false,
    //'parent'     => 0,
    'orderby'    => 'name',
    'order'      => 'ASC',
]);

$cats_for_catering = [];
$cats_for_shop     = [];

foreach ($all_terms as $t) {
    $flags = strike_popular_flags($t->term_id);
    if (in_array('Для общепита', $flags, true)) $cats_for_catering[] = $t;
    if (in_array('Для магазина', $flags, true)) $cats_for_shop[] = $t;
}
?>

